# Serial 02–08: shared market and honest prelaunch shopping state.
(R/'assets/parent-guide.css').write_text('''
.mp-marketbar{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px max(4vw,16px);background:#faf6ef;border-bottom:1px solid #e8ddd0;color:#493d32;font:13px/1.5 Inter,system-ui,sans-serif}.mp-marketbar select{max-width:180px;min-height:44px;border:1px solid #d4c5b5;border-radius:6px;background:white;padding:8px;color:#493d32;font:inherit}.mp-marketbar a{color:inherit}.mp-skip{position:absolute;left:12px;top:-100px;background:white;padding:14px;z-index:20000}.mp-skip:focus{top:12px}:focus-visible{outline:3px solid #714414!important;outline-offset:4px!important}.mp-help{font:15px/1.6 Inter,system-ui,sans-serif;display:flex;gap:16px;flex-wrap:wrap;padding:24px 0;border-top:1px solid #e8ddd0;margin-top:24px}.mp-help a{color:#713d28!important;text-decoration:underline;text-underline-offset:3px}.mp-guide{max-width:1120px;margin:auto;padding:42px 5vw 64px;color:#423a32;font:16px/1.75 Inter,system-ui,sans-serif}.mp-guide h1{font-size:clamp(30px,5vw,48px);font-weight:500;line-height:1.12;letter-spacing:-.03em;max-width:760px}.mp-guide h2{font-size:26px;font-weight:500;line-height:1.25;margin-top:36px}.mp-guide h3{font-size:20px;font-weight:500}.mp-guide p{max-width:760px}.mp-guide a{color:#884b30;text-underline-offset:4px}.mp-lead{font-size:19px;color:#675b50}.mp-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.mp-panel{padding:24px;border:1px solid #eadfd3;border-radius:8px;background:#fdfaf6}.mp-panel img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:5px}.mp-cta{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:10px 18px;background:#a65d3e;color:white!important;border-radius:6px;text-decoration:none;margin:8px 8px 8px 0}.mp-guide details,.mp-product-help details{border-bottom:1px solid #e3d8cb;padding:16px 0}.mp-guide summary,.mp-product-help summary{cursor:pointer;font-weight:600;min-height:36px}.mp-table{width:100%;border-collapse:collapse}.mp-table th,.mp-table td{text-align:left;vertical-align:top;padding:14px;border-bottom:1px solid #e4d9cb}.mp-table-wrap{overflow:auto}.mp-product-help{font-size:14px;line-height:1.65;margin:20px 0}.mp-product-help a{color:#82462e}.mp-journeys{max-width:1260px;margin:0 auto;padding:20px 5vw 36px}.mp-journeys a{display:block;text-decoration:none;color:#493d32}.mp-journeys h2{font-size:22px;font-weight:500;margin:0 0 8px}.mp-journeys p{font-size:15px;line-height:1.6;margin:0}.mp-filter-actions{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:12px 0;font-size:14px}.mp-filter-actions button{min-height:44px;padding:10px 14px;border:1px solid #c8b7a8;background:white;border-radius:5px;color:#68452f}.detail-description{max-height:none!important;font-size:15px!important}.prototype-note,.checkout-note,.field,.product-meta{font-size:12px!important}.product-actions a{padding:10px;min-height:44px;font-size:13px;color:#82462e}.product-actions button,.chip{min-height:44px}.gallery-main>img{object-fit:contain!important}.mp-region-in,.mp-region-us{display:none}html[data-market="in"] .mp-region-in,html[data-market="us"] .mp-region-us{display:block}@media(max-width:680px){.mp-grid{grid-template-columns:1fr}.mp-marketbar{font-size:12px;align-items:center}.mp-marketbar span{max-width:55%}.mp-marketbar select{width:138px}.mp-guide{padding-top:28px}.mp-panel{padding:20px}.filter-tools{flex-wrap:wrap}.filter-tools input{min-width:0;width:100%;flex-basis:100%}.filter-tools select{max-width:100%;flex:1}.mp-table{font-size:14px}.mp-table td,.mp-table th{padding:10px}.mp-help{gap:12px}.dialog{padding:12px!important}.gallery{grid-template-columns:1fr!important}.gallery-thumbs{flex-direction:row!important;max-height:none!important}.gallery-main,.gallery-main>img{min-height:220px!important}.detail-grid{grid-template-columns:1fr!important}.cart-line{grid-template-columns:48px 1fr!important}.cart-line>strong{grid-column:2}.cart-line img{width:48px!important}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation:none!important;transition:none!important}}
''')
(R/'assets/market.js').write_text('''(()=>{'use strict';const match=location.pathname.match(/^\\/(us|in)\\//),q=new URLSearchParams(location.search);let stored;try{stored=localStorage.getItem('mimipip_market')}catch{}const market=match?.[1]||(['us','in'].includes(q.get('market'))?q.get('market'):stored==='in'?'in':'us');window.MIMIPIP_MARKET=market;document.documentElement.dataset.market=market;document.documentElement.lang=market==='in'?'en-IN':'en-US';try{localStorage.setItem('mimipip_market',market)}catch{}document.addEventListener('DOMContentLoaded',()=>{const bar=document.createElement('div');bar.className='mp-marketbar';bar.innerHTML='<span>Explore & plan · Ordering opens soon. <a href="/shipping/">Delivery information</a></span><label><span class="sr-only" style="position:absolute;clip:rect(0,0,0,0)">Shopping country</span><select aria-label="Shopping country"><option value="us">United States · USD</option><option value="in">India · INR</option></select></label>';bar.querySelector('select').value=market;bar.querySelector('select').onchange=e=>{const target=e.target.value;try{localStorage.setItem('mimipip_market',target)}catch{}const u=new URL(location.href);if(match)u.pathname=u.pathname.replace(/^\\/(us|in)\\//,'/'+target+'/');u.searchParams.set('market',target);location.assign(u.href)};document.body.prepend(bar);const main=document.querySelector('main');if(main){if(!main.id)main.id='main-content';main.tabIndex=-1;const skip=document.createElement('a');skip.className='mp-skip';skip.href='#'+main.id;skip.textContent='Skip to content';document.body.prepend(skip)}const footer=document.querySelector('footer');if(footer){const links=document.createElement('nav');links.className='mp-help';links.setAttribute('aria-label','Shopping help');links.innerHTML=[['nursery','Baby nursery'],['toddler','Toddler rooms'],['wall-stickers','Wall stickers'],['guides/choose','Compare formats'],['guides/measure','Measuring'],['guides/surfaces','Wall suitability'],['guides/installation','Installation & care'],['samples','Samples'],['shipping','Shipping'],['returns','Returns'],['faq','FAQ'],['contact','Contact'],['privacy','Privacy']].map(([p,t])=>'<a href="/'+p+'/">'+t+'</a>').join('');footer.append(links)}document.querySelectorAll('a[href="/bathroom-buddies/little-ocean/"]').forEach(a=>a.href='/'+market+'/bathroom-buddies/little-ocean/');});})();''')
# Guides: factual planning advice and adapted Zyvorah wallpaper policy, separate sticker release.
pages={
'nursery':('A little world, ready for their arrival.','Baby nursery wall decor', '''<p class="mp-lead">Start with a room you enjoy spending time in. Choose a gentle scene, check the wall, and plan the details before decorating.</p><div class="mp-grid"><article class="mp-panel"><img src="/nafas/images/nafas-daisy-days-room-kidsroom.webp" alt="Daisy Days wallpaper room inspiration"><h2>A quieter backdrop</h2><p>Try florals, gardens or a soft sky. Look at the design beside your crib, curtains and flooring in daylight and evening light.</p><a class="mp-cta" href="/?stage=Nursery&interest=nature#shop">Explore nursery nature designs</a></article><article class="mp-panel"><h2>One wall or a few small details?</h2><p>A mural creates one continuous scene. A border adds a band of pattern. Individual decals allow a lighter arrangement; our Little Ocean sticker collection is coming soon.</p><a class="mp-cta" href="/guides/choose/">Compare your options</a><a href="/?stage=Nursery&interest=sky#shop">Explore sky designs</a></article></div><h2>Your nursery planning checklist</h2><ol><li>Pick the wall and record its full width and height, including areas behind furniture.</li><li>Check the paint finish, texture, age and any damp patches before choosing a material.</li><li>Ask for a printed sample where available. Screen colors and room illustrations are not a substitute for the actual print.</li><li>Confirm the final crop, panel layout, material and arrival estimate before scheduling installation.</li><li>Keep loose backing, tools and any detachable decorative pieces away from children. Decorative stickers are not toys.</li></ol><p>Nursery is a design-browsing category, not a product certification. Review the exact material and intended surface for your chosen item.</p><a class="mp-cta" href="/?stage=Nursery#shop">Browse all nursery designs</a><a href="/guides/surfaces/">Check your wall first</a>'''),
 'toddler':('Make room for their next big little idea.','Toddler room wall decor','''<p class="mp-lead">Animals today, adventures tomorrow. Start with what interests them, then choose a format that works for the room you have.</p><div class="mp-grid"><article class="mp-panel"><img src="/nafas/images/nafas-panda-and-tweet-room-kidsroom.webp" alt="Panda and Tweet wallpaper in a child's room"><h2>Follow their curiosity</h2><p>Choose a character, garden or sky they recognize. Keep the rest of the room simple so the design has room to breathe.</p><a class="mp-cta" href="/?stage=Toddler&interest=animals#shop">Animals & birds</a><a href="/?stage=Toddler&interest=adventure#shop">Explore adventures</a></article><article class="mp-panel"><h2>Plan for everyday life</h2><p>Ask how the exact material can be cleaned and removed. A matte wallpaper finish does not automatically mean peel-and-stick, reusable or scrub-resistant.</p><a class="mp-cta" href="/guides/installation/">Care & removal guide</a><a href="/floor-games/">Explore floor-game concepts</a></article></div><h2>Before you choose</h2><ul><li>Measure around furniture and leave the room's working areas clear.</li><li>Save a few designs to compare with another adult. Your shortlist stays in this browser.</li><li>Keep decorative wall stickers separate from floor products. Wet-area grip performance requires its own testing.</li><li>Use floor-game activities according to the child's abilities, with adult supervision; walking alternatives are included in the play guides.</li><li>Confirm wall preparation, sample availability and delivery before planning a birthday or room reveal.</li></ul><p>Toddler tags describe room inspiration, not an age rating or a safety test result.</p><a class="mp-cta" href="/?stage=Toddler#shop">Browse toddler designs</a>'''),
 'wall-stickers':('Small details. A whole new story.','Wall stickers & decorative decals','''<p class="mp-lead">Individual illustrations for a playful corner, a bathroom mirror or a smaller room refresh.</p><div class="mp-grid"><article class="mp-panel"><img src="/bathroom-stickers/assets/little-ocean-flat.png" alt="The twenty Little Ocean illustrations"><h2>Meet Little Ocean</h2><p>Twenty coordinated illustrations, with fixed design dimensions and surface-specific versions. Decorative and floor-grip versions are separate products under development.</p><a class="mp-cta" href="/bathroom-buddies/little-ocean/">Explore pieces, sizes & placements</a></article><article class="mp-panel"><h2>What to check in a sticker set</h2><ul><li>Number of pieces and the size of each illustration.</li><li>Which surface the material is made for.</li><li>Whether the preview shows all supplied pieces or one possible arrangement.</li><li>Tested adhesion, cleaning and removal instructions.</li></ul><p>Little Ocean is coming soon. Do not use decorative stickers as floor grips or infer wet-area suitability from a placement illustration.</p></article></div><a href="/guides/choose/">Decals or wallpaper? Compare formats</a>'''),
 'guides/choose':('Which format fits your room?','Compare wallpaper, borders & stickers','''<p class="mp-lead">Choose the size of the change before choosing the design.</p><div class="mp-table-wrap"><table class="mp-table"><thead><tr><th>Format</th><th>Best starting point</th><th>Check before ordering</th></tr></thead><tbody><tr><td>Wallpaper / mural</td><td>A full feature wall or continuous scene</td><td>Full wall size, final crop, panel layout, material and fitting method</td></tr><tr><td>Wall border</td><td>A narrow band of pattern</td><td>Border height, supplied length, repeat and corners</td></tr><tr><td>Individual wall stickers</td><td>A smaller arrangement of separate motifs</td><td>Piece count, individual dimensions and exact surface compatibility</td></tr><tr><td>Floor games</td><td>A designated area for play</td><td>Overall footprint, clear surrounding space, floor testing and instructions</td></tr></tbody></table></div><h2>Choose by the room, then the finish</h2><p>A smooth matte surface describes appearance, not adhesive type. Paste-the-wall murals and peel-and-stick decals need different preparation and fitting instructions. Confirm the selected product's specification.</p><p>Height charts are coming soon. Browse current concepts without assuming all categories are available to order.</p><a class="mp-cta" href="/nursery/">Plan a nursery</a><a class="mp-cta" href="/toddler/">Plan a toddler room</a>'''),
 'guides/measure':('A good fit starts with your wall.','How to measure your wall','''<p class="mp-lead">Use a tape measure and record the dimensions before choosing the final composition.</p><ol><li><strong>Width:</strong> measure across the top, center and bottom. Keep the largest measurement.</li><li><strong>Height:</strong> measure left, center and right from the top of the baseboard to the ceiling. Keep the largest measurement.</li><li><strong>Record accurately:</strong> note your units. One foot is 12 inches or 30.48 cm. Round up rather than down.</li><li><strong>Map obstacles:</strong> note doors, windows, outlets and furniture. Do not subtract these areas from a continuous mural without checking the layout.</li><li><strong>Check the proof:</strong> confirm where the picture starts, where the joins fall and how the design is cropped. Confirm fitting allowance before production.</li></ol><p>For sloped ceilings, record the enclosing rectangle and a sketch. For multiple walls, measure each wall separately and mark corners. A room photograph alone cannot establish accurate dimensions.</p><p>The product planner calculates wall area only. It does not generate a production proof, panel plan or final price.</p><a class="mp-cta" href="/contact/">Ask about your wall layout</a>'''),
 'guides/surfaces':('Will it work on your wall?','Wall suitability & materials','''<p class="mp-lead">The wall underneath matters as much as the design on top.</p><div class="mp-grid"><article class="mp-panel"><h2>Tell us about the surface</h2><ul><li>Smooth or textured: include orange-peel, knockdown or heavy plaster texture.</li><li>Paint type, finish and when it was applied.</li><li>Any peeling, flaking, dust, damp or previous wallcovering.</li><li>Whether the space gets steam or direct splashes.</li></ul></article><article class="mp-panel"><h2>Check the exact material</h2><p>The wallpaper catalog records finishes such as smooth matte and linen feel. The final material, adhesive and fitting instructions must match your chosen design.</p><p>We do not make a site-wide PVC-free, low-emissions or GREENGUARD claim. Ask for product-specific evidence where that matters to your selection.</p></article></div><h2>Fresh paint and textured walls</h2><p>Follow the paint manufacturer's full cure time and the wallcovering supplier's preparation requirements. Dry-to-touch is not proof that a wall is ready. Do not assume adhesion to textured, chalky or damaged finishes; request a material test first.</p><h2>Bathrooms and floors</h2><p>Standard wallpaper is not intended for direct shower exposure. Decorative wall stickers and wet-area floor products have different requirements. Little Ocean's adhesion and grip checks must be completed before release.</p><h2>Renting?</h2><p>Check permission and the existing paint condition. Removal results depend on the finish, preparation and material; no universal damage-free or reusable promise is made.</p><a class="mp-cta" href="/samples/">Ask about a sample</a>'''),
 'guides/installation':('Prepare well. Enjoy the room longer.','Installation, cleaning & removal','''<p class="mp-lead">Use the fitting instructions supplied for the exact material. This overview helps you plan the work.</p><h2>Before installation</h2><p>Check the artwork, dimensions and panel sequence before cutting or hanging. The wall should be sound, smooth, clean and dry. Resolve damp, loose paint and uneven areas first. Keep tools and loose backing away from children.</p><h2>Paste-the-wall wallpaper</h2><p>For a confirmed paste-the-wall finish, apply the specified paste to the wall in manageable panel-width sections, hang the dry numbered panel, align the design and smooth outward. Follow the supplied join and trimming instructions. Do not use this method for self-adhesive decals.</p><h2>Decorative stickers</h2><p>First check material-specific surface and preparation instructions, then plan the arrangement. Do not stretch artwork to match a room illustration. Little Ocean application and cleaning instructions will be finalized after material testing.</p><h2>Cleaning</h2><p>For the sourced matte wallpaper care guidance, use a barely damp soft cloth gently; avoid abrasive scrubbing and harsh cleaners. Check the product's instructions before cleaning other finishes.</p><h2>Removal</h2><p>Long-term paste-the-wall wallpaper may need dampening before peeling. Removed panels should not be expected to be reusable. Paint condition affects the result. Follow material-specific removal guidance for stickers.</p><a class="mp-cta" href="/guides/surfaces/">Check surface suitability</a>'''),
 'samples':('See the finish in your own light.','Wallpaper samples','''<p class="mp-lead">A printed sample helps you compare color, texture and finish with the room around it.</p><h2>India</h2><p>Our wallpaper sample reference is Zyvorah's printed design-sample service at ₹200 per sample within India. Ask us to confirm that your chosen MimiPip design and finish are available before paying or scheduling installation.</p><h2>United States</h2><p>International sample fulfillment is not currently confirmed for MimiPip. Ask for available close-up photographs and a material specification. A screen image cannot guarantee a printed color match.</p><h2>What to include</h2><p>Send the design name or link, preferred finish and delivery country. Sticker and floor-game samples require separate material confirmation.</p><a class="mp-cta" href="mailto:hello@mimipip.com?subject=MimiPip%20sample%20availability">Ask about a sample</a><p>Your email app opens; this does not place a sample order.</p>'''),
 'shipping':('Plan the room. Then plan the arrival.','US & India shipping information','''<p class="mp-lead">MimiPip ordering is not open yet. The wallpaper planning terms below are adapted from Zyvorah; confirm the final quote and destination before arranging installation.</p><h2>United States</h2><p>For the sourced made-to-order wallpaper service, allow up to 5 working days for production, followed by an indicative 5–18 working days in international transit depending on destination. These are estimates, not a guaranteed arrival date.</p><p>International wallpaper delivery is included in the country-adjusted USD quote. Destination duties, local taxes and customs charges are separate and the recipient's responsibility. US wallpaper prices still need to be configured on MimiPip.</p><h2>India</h2><p>Standard wallpaper: dispatch within 5 working days, then typically 2–4 working days in transit. Standard delivery is included; wallpaper has a 20 sq ft billing minimum and 4 ft minimum chargeable width.</p><p>Express dispatch: within 2 working days, at ₹1,000 per wallpaper plus ₹500 per order. This accelerates production and dispatch, not courier transit. Festivals and long weekends can affect timing.</p><h2>Stickers, floor games and samples</h2><p>Wallpaper delivery terms do not automatically apply to these categories. Final material release, stock, dispatch and delivery charges will be confirmed separately before ordering opens.</p><h2>Before you commit</h2><p>Ask for the dispatch date, transit estimate, ZIP or PIN-code coverage, total price and any destination charges. Wait for delivery and inspect the product before booking installation.</p><a class="mp-cta" href="/contact/">Ask about delivery</a>'''),
 'returns':('Know the details before you choose.','Returns, cancellation & product issues','''<p class="mp-lead">Ordering is not yet open. These made-to-order wallpaper terms are adapted from Zyvorah and will be shown with the final MimiPip order terms.</p><h2>Made-to-order wallpaper</h2><p>Request cancellation within 12 hours of ordering and before printing begins. Once printing starts, cancellation and change-of-mind returns are unavailable because the artwork is printed to your measurements.</p><h2>Measurements and color</h2><p>Check your dimensions and approved composition carefully. Screens vary; slight differences from the printed color are expected. A printed sample is the best way to assess a color before ordering.</p><h2>Damage or a print fault</h2><p>Report transit damage within 48 hours, or a manufacturing fault within 7 days of delivery. Include the order reference and clear photographs of the product and packaging. Retain the packaging and avoid installing an affected panel until support has assessed it.</p><p>For a valid claim, the affected panels are reprinted or replaced. If reprinting is not possible, the resolution may be a credit or refund. Installation damage is separate from a manufacturing fault.</p><h2>Stickers and floor games</h2><p>Their return eligibility and procedures will be confirmed before these products are released. Do not assume that a custom-wallpaper policy also governs a ready-size sticker set.</p><a class="mp-cta" href="mailto:hello@mimipip.com?subject=MimiPip%20product%20support">Contact product support</a>'''),
 'contact':('Let’s work out the little details.','Contact MimiPip','''<p class="mp-lead">Choosing between two designs, checking a surface or planning a whole room?</p><a class="mp-cta" href="mailto:hello@mimipip.com">hello@mimipip.com</a><h2>Help us understand the room</h2><ul><li>The design name or product-page link.</li><li>United States or India, plus your ZIP or PIN code if asking about delivery.</li><li>Wall width and height with units.</li><li>Paint finish, texture and when the wall was painted.</li><li>Your question: material, sample, layout, delivery or care.</li></ul><p>You do not need to share a child's full name or a home address to ask about a design. Email opens in your own app and is sent only when you choose to send it.</p><h2>Current availability</h2><p>Browse designs, plan dimensions and save a shortlist. MimiPip does not currently accept online orders or payments. An enquiry is not a reservation.</p><a href="/faq/">Read common questions</a>'''),
 'privacy':('Your choices stay yours.','Privacy & cookies','''<p class="mp-lead">This page describes the current browse-and-plan website.</p><h2>Saved designs and country</h2><p>Your selected market and saved designs are kept in this browser's local storage when available. They are not an account and do not sync across devices. Remove saved designs in the saved-design panel or clear the site's storage in your browser.</p><h2>Name preview</h2><p>A name typed into the wallpaper badge preview is used on the current page. It is not included in the saved-design record or analytics events. It does not create a print file or personalization order.</p><h2>Optional analytics</h2><p>Google Analytics loads only after you accept optional analytics. It measures page visits and design exploration. Our tracking does not include name-preview entries or enquiry text. Use Cookie settings in the footer to change your choice.</p><h2>Email and external content</h2><p>Contact links open your email app. Your email provider handles sending, and our support mailbox receives what you choose to send. Product imagery, fonts and existing collection media may load from third-party hosts, which receive normal network request information.</p><h2>Orders</h2><p>No checkout address or payment details are collected by this website. A complete commerce privacy notice will accompany the order service when it opens.</p><p>For questions about your data, contact <a href="mailto:hello@mimipip.com">hello@mimipip.com</a>.</p>'''),
 'faq':('A few things worth knowing first.','Questions from parents','''<p class="mp-lead">Practical answers for a nursery, toddler room or small refresh.</p>'''+''.join('<details><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in [
 ('Can I order now?','Not yet. Browse the collections, save designs and contact us for product information. No payment or order is taken online.'),
 ('Are these wall stickers or wallpaper?','Both formats are presented, with separate categories. Wallpaper covers a measured wall; stickers are individual motifs. <a href="/guides/choose/">Compare formats</a>.'),
 ('Will they work on textured walls?','Compatibility depends on the exact material, paint and texture. Do not assume that a peel-and-stick product works on orange-peel, knockdown or rough plaster. <a href="/guides/surfaces/">Check the surface guide</a>.'),
 ('Is every wallpaper self-adhesive?','No. A matte finish is not an adhesive specification. Check the material and fitting method for the chosen design.'),
 ('Does a nursery tag mean certified child-safe?','No. Stage tags help browse designs. They do not establish material certification, emissions testing or an age rating.'),
 ('How large are the designs?','Wallpaper is planned around wall measurements. Little Ocean has a piece-by-piece dimension table. Room illustrations show possible styling; use product dimensions for planning.'),
 ('Can I add a name?','You can try a name badge visually. It is a concept preview, not a production proof or an ordered customization.'),
 ('Can I move or reuse it later?','Do not assume reuse or damage-free removal. Paste-the-wall wallpaper is intended for long-term installation. Ask about the exact material before choosing it for a rental.'),
 ('Do you serve the US and India?','The website supports both browsing markets. <a href="/shipping/">Read regional shipping information</a> and confirm a quote before planning installation.'),
 ('Can I get a sample?','Ask about availability for the design and country. India wallpaper samples use a ₹200 reference service; international samples are not confirmed. <a href="/samples/">Sample information</a>.'),
 ('Can decorative stickers go on the bathroom floor?','No. Decorative stickers must not be substituted for a floor-grip material. The separate Little Ocean floor version is awaiting material and wet-area performance validation.'),
 ('Can I compare favorites with my partner?','Save designs on the homepage, or share the product link. Saved designs stay in the current browser; a shared catalog URL preserves filter choices but not your private shortlist.')]))
}
for slug,(heading,title,body) in pages.items():
 out=R/slug/'index.html';out.parent.mkdir(parents=True,exist_ok=True)
 out.write_text(f'''<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | MimiPip</title><meta name="description" content="{E(title)}: practical information for parents planning a nursery or toddler room in the United States and India."><link rel="canonical" href="https://mimipip.com/{slug}/"><link rel="stylesheet" href="/assets/parent-guide.css"><script src="/assets/market.js"></script><script defer src="/analytics.js"></script></head><body><header class="mp-guide" style="padding-top:20px;padding-bottom:16px;display:flex;justify-content:space-between;gap:18px;align-items:center"><a href="/"><img src="/assets/mimi-pip/wordmark.png" width="140" alt="MimiPip home"></a><a href="/#shop">Browse designs</a></header><main class="mp-guide"><nav aria-label="Breadcrumb"><a href="/">Home</a> / {E(title)}</nav><h1>{E(heading)}</h1>{body}</main><footer class="mp-guide">MimiPip · Little details. Lovely little worlds.</footer></body></html>''')
# Homepage edits, preserving the actual latest published collection.
p=R/'index.html';s=p.read_text();s=s.replace('<html lang="en-IN">','<html lang="en-US">')
s=s.replace('Browse collection</a>','Browse designs</a>')
